#!/usr/bin/env bash
# Generated by cn from the declared packs' env declarations: do not edit,
# run cn adopt to regenerate. The web environment's setup script runs it.
# It pre-warms the pinned engine, then runs each pack's setup and its
# probe; exit 1 when a pack's environment is not in place afterwards.
cd "$(dirname "$0")/../.." || exit 1
npx --yes --prefer-offline @claudinite/setup@1.0.1 >/dev/null || echo 'cn env: the engine was not pre-warmed; SessionStart fetches it' >&2
failed=0

echo '=== Node dependencies (npm ci) (pack node) ==='
if ! (
( cd "." && npm ci ) || true
); then
  echo 'cn env: Node dependencies (npm ci) (pack node): setup failed' >&2
  failed=1
elif ! (
[ -d "./node_modules" ]
); then
  echo 'cn env: Node dependencies (npm ci) (pack node): setup ran, but its probe still fails' >&2
  failed=1
fi

exit $failed
